/**
 * כוריאוגרפיית הגלילה של דף הבית (REDESIGN-PLAN §4 + §6, גרסה 2).
 * כל סצנה כאן היא orient או reveal: התוכן "מוחזק בחלל" — מגיע מעומק (הטיה לאחור + מרחק) ומתיישר מולכם,
 * וכשאתם ממשיכים הוא נסוג. דסקטופ: scrub צמוד לגלילה; מגע: כניסות קצרות בזמן; הפחתת תנועה: כלום (הכול גלוי).
 */
import { gsap, ScrollTrigger, reduced, finePointer, fwd, isRTL } from './core';

const wide = () => matchMedia('(min-width: 1000px)').matches;

export function initScenes() {
  if (reduced()) return;
  const mm = gsap.matchMedia();

  /* ---------- הגעה: הכותרת נסוגה לעומק כשמתחילים לגלול (המצלמה של הבמה ממשיכה קדימה) ---------- */
  const arr = document.querySelector<HTMLElement>('.arrival');
  if (arr) {
    const copy = arr.querySelector('.arr-copy'), doors = arr.querySelector('.doors');
    gsap.timeline({ scrollTrigger: { trigger: arr, start: 'top top', end: 'bottom top', scrub: 0.6 } })
      .to(copy, { yPercent: -18, scale: 0.94, opacity: 0, ease: 'none', transformOrigin: '50% 100%' }, 0)
      .to(doors, { y: -80, opacity: 0, ease: 'power1.in', duration: 0.45 }, 0);
  }

  /* ---------- יריעות וכרטיסים: מגיעים מעומק, מתיישרים, נסוגים ---------- */
  // דסקטופ בלבד: במובייל יריעה גבוהה "מגיעה מעומק" בזמן שכבר קוראים אותה — דוד: "נטען מהר מדי, מפספסים את הפסקה הראשונה"
  const depthEls = wide() ? gsap.utils.toArray<HTMLElement>('[data-depth]') : [];
  depthEls.forEach((el) => {
    const kind = el.dataset.depth; // 'rise' (ברירת מחדל) | 'side'
    const from = kind === 'side'
      ? { rotationY: -14 * fwd(), x: 90 * -fwd(), z: -160, opacity: 0 }
      : { rotationX: 16, y: 150, z: -180, opacity: 0 };
    gsap.set(el, { transformPerspective: 1400, transformOrigin: kind === 'side' ? (isRTL() ? '100% 50%' : '0% 50%') : '50% 100%' });
    gsap.fromTo(el, from, {
      rotationX: 0, rotationY: 0, x: 0, y: 0, z: 0, opacity: 1, ease: 'power2.out',
      scrollTrigger: { trigger: el, start: 'top bottom', end: 'top 72%', scrub: finePointer() ? 0.5 : true }, // מתיישר עוד לפני שהטקסט מגיע לגובה הקריאה
    });
  });

  /* ---------- מוכרים: קו זהב שגדל לאורך השלבים ---------- */
  const line = document.querySelector<HTMLElement>('.steps-line i');
  const steps = document.querySelector<HTMLElement>('.steps');
  if (line && steps) {
    gsap.fromTo(line, { scaleY: 0 }, { scaleY: 1, ease: 'none', scrollTrigger: { trigger: steps, start: 'top 60%', end: 'bottom 60%', scrub: true } });
  }

  /* ---------- עיתונות: השורות נכנסות בכיוון הקריאה, מדורגות ---------- */
  const rows = gsap.utils.toArray<HTMLElement>('.press-row');
  if (rows.length) {
    gsap.from(rows, {
      x: 80 * -fwd(), opacity: 0, duration: 1, ease: 'expo.out', stagger: 0.09,
      scrollTrigger: { trigger: rows[0], start: 'top 85%', once: true },
    });
  }

  /* ---------- שמרית והילה: עומק בתוך המסגרת (התמונה זזה לאט מהמסגרת) ---------- */
  const img = document.querySelector<HTMLElement>('.photo img');
  const frame = document.querySelector<HTMLElement>('.photo');
  if (img && frame) {
    gsap.fromTo(img, { yPercent: -6, scale: 1.14 }, { yPercent: 6, scale: 1.14, ease: 'none', scrollTrigger: { trigger: frame, start: 'top bottom', end: 'bottom top', scrub: true } });
  }

  /* ---------- סרגל הפרקים ---------- */
  initRail();
}

function initRail() {
  const rail = document.querySelector<HTMLElement>('.rail');
  if (!rail) return;
  const fill = rail.querySelector<HTMLElement>('.rail-fill');
  const items = Array.from(rail.querySelectorAll<HTMLAnchorElement>('a[data-for]'));
  const secs = items.map((a) => document.getElementById(a.dataset.for!)).filter(Boolean) as HTMLElement[];
  ScrollTrigger.create({
    start: 0, end: 'max',
    onUpdate: (self) => { fill && gsap.set(fill, { scaleY: self.progress }); },
  });
  secs.forEach((s, i) => ScrollTrigger.create({
    trigger: s, start: 'top 55%', end: 'bottom 55%',
    onToggle: (self) => { if (self.isActive) items.forEach((a, j) => a.toggleAttribute('aria-current', i === j)); },
  }));
  ScrollTrigger.create({ trigger: secs[0], start: 'bottom 80%', onEnter: () => rail.classList.add('show'), onLeaveBack: () => rail.classList.remove('show') });
}
